const TEXT = {
  rerun_review: ['Review timer', 'No review result after 12 hours, so the review was cleared for a rerun'],
  refund_expired: ['Deadline timer', 'Deadline passed with no delivery, so the buyer was refunded'],
  finalize_default: ['Dispute timer', 'No escalation or DAO ruling in time, so the re-check result stands'],
};
const ROLE = { rerun_review: 'review_timeout', refund_expired: 'deadline_refund', finalize_default: 'dispute_default' };
const args = $('Timer args').all().map((i) => i.json);
return $input.all().map(({ json: r }, i) => {
  const a = args[i] || {};
  const method = a.method || r.method;
  const [label, text] = TEXT[method] || ['Timer', method];
  const runId = 'timer-' + Date.now() + '-' + i;
  return { json: {
    runId, ownerId: a.buyerId || null, agentId: null, jobId: a.jobId || r.jobId,
    actorLabel: label,
    message: r.ok ? `${text} (tx ${r.txHash})` : `${label} call ${method} refused: ${r.error}`,
    severity: r.ok ? 'ok' : 'warn',
    data: { method, txHash: r.txHash, ok: r.ok },
    notify: { runId, role: ROLE[method] || 'timer', ok: r.ok, jobId: a.jobId || r.jobId,
              result: { method, txHash: r.txHash, ownerId: a.buyerId || null }, error: r.error || null },
  } };
});

// The platform signer makes the call. ownerId stays null so a refusal
// does not count toward the guardian's rejected-call rule for the buyer.
return $input.all().map(({ json: m }) => ({ json: {
  signer: 'platform', method: m.method,
  args: { job_id: m.chain_job_id },
  ownerId: null, jobId: m.job_id, buyerId: m.buyer_id,
  amount: m.amount == null ? null : Number(m.amount),
} }));

// Nest re-runs the buyer agent with the private max price
return $input.all().map(({ json: j }) => ({ json: {
  notify: { runId: 'window-' + Date.now(), role: 'buyer_window', ok: true, jobId: j.job_id,
            result: { ownerId: j.buyer_id }, error: null },
} }));
